import math
from dataclasses import dataclass


@dataclass
class Order:
    item_id: str
    quantity: int
    unit_price: float


class Inventory:
    def __init__(self, warehouse):
        self.warehouse = warehouse
        self.stock = {}
        self.reserved = {}

    def restock(self, item_id, amount):
        current = self.stock.get(item_id, 0)
        self.stock[item_id] = current + amount
        return self.stock[item_id]

    def available(self, item_id):
        on_hand = self.stock.get(item_id, 0)
        held = self.reserved.get(item_id, 0)
        return on_hand - held


def compute_total(order, tax_rate):
    subtotal = order.quantity * order.unit_price
    tax = subtotal * tax_rate
    shipping = 0.0 if subtotal > 50 else 5.99
    return round(subtotal + tax + shipping, 2)


def apply_discount(total, code):
    discounts = {"SAVE10": 0.10, "SAVE20": 0.20, "HALF": 0.50}
    factor = discounts.get(code, 0.0)
    return math.floor(total * (1 - factor) * 100) / 100

